// Synthetic replica of @react-native-async-storage/async-storage sources (TS).
// The published package points its "react-native" field at TypeScript whose
// default export proxies a native storage module (RNCAsyncStorage). We resolve
// the native handle off the React Native default export so the bundle resolves
// cleanly; the handle is null at build time because the native module is only
// registered on a device, so reads and writes never reach native storage.
import ReactNative from "react-native";

const RNCAsyncStorage =
  (ReactNative as { TurboModuleRegistry?: { get(name: string): unknown } }).TurboModuleRegistry?.get(
    "RNCAsyncStorage",
  ) ?? null;

export const ASYNC_STORAGE_OK = "ASYNC_STORAGE_OK";

type NativeStorage = {
  multiGet(keys: string[], callback: (error: unknown, values: [string, string][]) => void): void;
  multiSet(pairs: [string, string][], callback: (error: unknown) => void): void;
};

function getNativeStorage(): NativeStorage | null {
  return RNCAsyncStorage as NativeStorage | null;
}

export const AsyncStorage = {
  async getItem(key: string): Promise<string | null> {
    const native = getNativeStorage();
    if (!native) {
      return null;
    }
    return new Promise((resolve, reject) => {
      native.multiGet([key], (error, values) => {
        if (error) {
          reject(error);
          return;
        }
        resolve(values?.[0]?.[1] ?? null);
      });
    });
  },
  async setItem(key: string, value: string): Promise<void> {
    const native = getNativeStorage();
    if (!native) {
      return;
    }
    return new Promise((resolve, reject) => {
      native.multiSet([[key, value]], (error) => {
        if (error) {
          reject(error);
          return;
        }
        resolve();
      });
    });
  },
};

export default AsyncStorage;
